import { getSession } from '@/app/lib/auth'
import { forbidden } from 'next/navigation'
import { connection } from 'next/server'

export default async function AdminPage() {
  // This mock session does not read cookies or headers; check it on every request.
  await connection()
  const session = await getSession()

  if (session?.role !== 'admin') {
    forbidden()
  }

  return (
    <main style={{ maxWidth: 960, margin: '4rem auto', padding: '0 1.5rem' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}. You have access to the admin area.</p>
    </main>
  )
}

